1	/* runtime.h — the w2m guest runtime's view of guest memory (Sprint 035).
2	 *
3	 * Freestanding C compiled to AArch64 and run inside the managed VM (BLACKBOARD 2026-10-09, runtime
4	 * architecture). Addresses come from src/w2m/vm_backend.py as -D definitions: W2M_TEB_VA,
5	 * W2M_PEB_VA, W2M_TRANSPORT_VA, W2M_RING_VA. Offsets are specs/guest_state.json's, confirmed on
6	 * Windows in Sprint 034 (store/probe-runs/37989842529).
7	 */
8	#ifndef W2M_RUNTIME_H
9	#define W2M_RUNTIME_H
10	
11	typedef unsigned long long u64;
12	typedef unsigned int u32;
13	typedef unsigned char u8;
14	
15	/* TEB fields the runtime reads or writes (winternl.h and the Sprint 034 observations). */
16	struct w2m_teb {
17	    u8 reserved0[0x08];
18	    u64 stack_base;                  /* 0x08 NtTib.StackBase */
19	    u64 stack_limit;                 /* 0x10 NtTib.StackLimit */
20	    u8 reserved1[0x30 - 0x18];
21	    u64 self;                        /* 0x30 NtTib.Self */
22	    u8 reserved2[0x40 - 0x38];
23	    u64 client_process;              /* 0x40 ClientId.UniqueProcess */
24	    u64 client_thread;               /* 0x48 ClientId.UniqueThread */
25	    u8 reserved3[0x60 - 0x50];
26	    u64 process_environment_block;   /* 0x60 */
27	    u32 last_error_value;            /* 0x68 */
28	};
29	_Static_assert(__builtin_offsetof(struct w2m_teb, client_thread) == 0x48, "TEB ClientId.UniqueThread");
30	_Static_assert(__builtin_offsetof(struct w2m_teb, last_error_value) == 0x68, "TEB LastErrorValue");
31	
32	static inline struct w2m_teb *w2m_teb(void) { return (struct w2m_teb *)W2M_TEB_VA; }
33	
34	/* Host transport: the runtime fills a request, executes hvc #8, and reads the result. */
35	enum { W2M_HOST_WRITE = 1, W2M_HOST_EXIT = 2, W2M_HOST_CLOCK = 3, W2M_HOST_UNIMPLEMENTED = 4,
36	       W2M_HOST_RUNTIME_FAULT = 5 };
37	struct w2m_transport {
38	    u64 op;
39	    u64 arg[6];
40	    u64 result;
41	};
42	
43	/* Ring buffer: one record per service call, drained by the host after the run. */
44	struct w2m_ring_record {
45	    u64 api;
46	    u64 arg0;
47	    u64 ret;
48	};
49	struct w2m_ring {
50	    u64 count;                       /* records written, including any dropped past capacity */
51	    u64 capacity;
52	    struct w2m_ring_record rec[];
53	};
54	
55	/* The thread's state block (specs/guest_state.json 0.2.0 state_block; Sprint 040). Translated code
56	 * keeps the guest registers in host registers; the block holds them whenever the thread is not
57	 * running x86 code: in a service, at a fault, when stopped. */
58	struct w2m_state {
59	    u64 gpr[16];                     /* 0x000 rax rcx rdx rbx rsp rbp rsi rdi r8-r15 */
60	    u64 rip;                         /* 0x080 */
61	    u64 rflags;                      /* 0x088 materialized: CF PF AF ZF SF DF OF, IF and bit 1 */
62	    u64 flags_undefined;             /* 0x090 one bit per flag while undefined: C Z S O P A */
63	    u32 mxcsr;                       /* 0x098 */
64	    unsigned short x87_control_word; /* 0x09c */
65	    unsigned short x87_status_word;  /* 0x09e */
66	    u8 x87_tag_abridged;             /* 0x0a0 */
67	    u8 reserved0[7];
68	    u64 fs_base;                     /* 0x0a8 */
69	    u64 gs_base;                     /* 0x0b0 */
70	    u64 teb;                         /* 0x0b8 */
71	    u32 thread_state;                /* 0x0c0 */
72	    u32 suspend_count;               /* 0x0c4 */
73	    u64 af_operands[3];              /* 0x0c8 */
74	    u8 df;                           /* 0x0e0 */
75	    u8 reserved1[0x100 - 0xe1];
76	    u8 xmm[16][16];                  /* 0x100 */
77	    u8 ymm_high[16][16];             /* 0x200 */
78	    u8 st[8][16];                    /* 0x300 */
79	};
80	_Static_assert(sizeof(struct w2m_state) == 896, "state block size (spec 896)");
81	_Static_assert(__builtin_offsetof(struct w2m_state, rip) == 128, "state.rip");
82	_Static_assert(__builtin_offsetof(struct w2m_state, mxcsr) == 152, "state.mxcsr");
83	_Static_assert(__builtin_offsetof(struct w2m_state, af_operands) == 200, "state.af_operands");
84	_Static_assert(__builtin_offsetof(struct w2m_state, df) == 224, "state.df");
85	_Static_assert(__builtin_offsetof(struct w2m_state, xmm) == 256, "state.xmm0");
86	_Static_assert(__builtin_offsetof(struct w2m_state, st) == 768, "state.st0");
87	
88	/* Windows x64 EXCEPTION_RECORD and CONTEXT, at the offsets probes/guest_state measured on the
89	 * runner (specs/guest_state.json windows.*). Only the fields the runtime writes are named. */
90	struct w2m_exception_record {
91	    u32 code;                        /* 0 */
92	    u32 flags;                       /* 4 */
93	    u64 record;                      /* 8 */
94	    u64 address;                     /* 16 */
95	    u32 number_parameters;           /* 24 */
96	    u32 pad;
97	    u64 information[15];             /* 32 */
98	};
99	_Static_assert(sizeof(struct w2m_exception_record) == 152, "EXCEPTION_RECORD size");
100	
101	struct w2m_context {
102	    u64 p_home[6];                   /* 0 */
103	    u32 context_flags;               /* 48 */
104	    u32 mx_csr;                      /* 52 */
105	    unsigned short seg_cs, seg_ds, seg_es, seg_fs, seg_gs, seg_ss;   /* 56 */
106	    u32 eflags;                      /* 68 */
107	    u64 dr[6];                       /* 72 */
108	    u64 gpr[16];                     /* 120 Rax Rcx Rdx Rbx Rsp Rbp Rsi Rdi R8-R15 */
109	    u64 rip;                         /* 248 */
110	    struct {                         /* 256 FltSave: XMM_SAVE_AREA32 */
111	        unsigned short control_word, status_word;
112	        u8 tag_word, reserved1;
113	        unsigned short error_opcode;
114	        u32 error_offset;
115	        unsigned short error_selector, reserved2;
116	        u32 data_offset;
117	        unsigned short data_selector, reserved3;
118	        u32 mx_csr, mx_csr_mask;
119	        u8 float_registers[8][16];   /* 32 */
120	        u8 xmm_registers[16][16];    /* 160 */
121	        u8 reserved4[96];
122	    } flt_save;
123	    u8 vector_register[26][16];      /* 768 */
124	    u64 vector_control;              /* 1184 */
125	    u64 debug_control;               /* 1192 */
126	    u64 last_branch_to_rip, last_branch_from_rip, last_exception_to_rip, last_exception_from_rip;
127	};
128	_Static_assert(sizeof(struct w2m_context) == 1232, "CONTEXT size");
129	_Static_assert(__builtin_offsetof(struct w2m_context, gpr) == 120, "CONTEXT.Rax");
130	_Static_assert(__builtin_offsetof(struct w2m_context, rip) == 248, "CONTEXT.Rip");
131	_Static_assert(__builtin_offsetof(struct w2m_context, flt_save) == 256, "CONTEXT.FltSave");
132	_Static_assert(__builtin_offsetof(struct w2m_context, vector_control) == 1184, "CONTEXT.VectorControl");
133	
134	/* What the EL1 exception vector saves (src/w2m/vm_backend.py exception entry). */
135	struct w2m_save_area {
136	    u64 x[31];
137	    u64 pad;
138	    u64 esr, far, elr;               /* 0x100 */
139	    u64 sw_code, sw_rip;             /* 0x118: an exception the host raised (an unmasked SIMD exception
140	                                        found by the slow path), or 0 for a hardware exception */
141	    u8 pad2[0x200 - 0x128];
142	    u8 q[16][16];                    /* 0x200: V0-V15, which hold XMM0-15 */
143	};
144	_Static_assert(__builtin_offsetof(struct w2m_save_area, sw_code) == 0x118, "save.sw_code");
145	_Static_assert(__builtin_offsetof(struct w2m_save_area, q) == 0x200, "save.q");
146	
147	/* Where the runtime leaves an exception it could not hand to a handler: the record and the
148	 * CONTEXT it built, for the host to read (Sprint 040; VEH dispatch is Sprint 047). */
149	struct w2m_exception_area {
150	    u64 magic;                       /* W2M_EXCEPTION_MAGIC once written */
151	    u64 pad;
152	    struct w2m_exception_record record;   /* 16 */
153	    u8 pad2[0x100 - 16 - 152];
154	    struct w2m_context context;      /* 0x100 */
155	};
156	#define W2M_EXCEPTION_MAGIC 0x7832774E4F495445ull     /* "ETIONw2x" */
157	
158	/* API identifiers in the ring; src/w2m/guest_runtime.py reads these lines. */
159	#define W2M_API_GetCurrentThreadId 1
160	#define W2M_API_SetLastError 2
161	#define W2M_API_GetLastError 3
162	#define W2M_API_GetStdHandle 4
163	#define W2M_API_WriteFile 5
164	#define W2M_API_ExitProcess 6
165	#define W2M_API_QueryPerformanceCounter 7
166	#define W2M_API_Exception 8
167	#define W2M_API_Cpuid 9
168	#define W2M_API_CreateFileW 10
169	#define W2M_API_CloseHandle 11
170	#define W2M_API_DeleteFileW 12
171	#define W2M_API_ReadFile 13
172	#define W2M_API_SetFilePointerEx 14
173	
174	/* Shared by runtime.c and file.c. */
175	u64 w2m_host(u64 op, u64 a0, u64 a1, u64 a2, u64 a3, u64 *second);
176	u64 w2m_logged(u64 api, u64 arg0, u64 ret);
177	void w2m_unimplemented(u64 api, u64 detail);
178	u64 w2m_file_write(u64 handle, u64 buffer, u64 count, u64 written);   /* file.c: WriteFile on a file handle */
179	
180	/* Host file primitives (src/w2m/file_bridge.py). */
181	enum { W2M_FILE_LOOKUP = 6, W2M_FILE_OPEN, W2M_FILE_CLOSE, W2M_FILE_READ, W2M_FILE_WRITE, W2M_FILE_SIZE,
182	       W2M_FILE_TRUNCATE, W2M_FILE_UNLINK };
183	
184	/* The contract surface a candidate may implement (contracts/windows.thread.last_error.set_get).
185	 * The default is tools/guest_runtime/last_error.c. */
186	void w2m_set_last_error(u32 code);
187	u32 w2m_get_last_error(void);
188	
189	#endif

